import { describe, it, expect } from 'vitest';
import {
  depositSinglePlan,
  withdrawSinglePlan,
  conversionImpactBps,
  minWithSlippage,
  type SingleSide,
} from '../src/chain/singleSided';
import { feeAtoms, walkLadder, maxGrossInput, type LadderLevel } from '../src/chain/swapMath';

/**
 * Golden vectors generated by the deployed program's own unit test
 * (`vault/program/src/lib.rs::tests::single_sided_golden_vectors` and
 * `single_sided_withdraw_golden_vectors`) for a single ladder level
 * `{sqrt_lo = 1<<64, sqrt_hi = 2<<64, liquidity = 10^28}` and fee 30 bps.
 * If the Rust answer changes, these must change with it.
 */
const LEVEL: LadderLevel = { sqrtLo: 1n << 64n, sqrtHi: 2n << 64n, liquidity: 10n ** 28n };
const LEVELS = [LEVEL];
const FEE_BPS = 30;
const BASE_NET = 1_000_000_000n;
const QUOTE_NET = 2_000_000_000n;
const TOTAL_SHARES = 1_000_000_000n;
const AMOUNT_IN = 100_000_000n;

function plan(side: SingleSide) {
  return depositSinglePlan({
    side,
    amountIn: AMOUNT_IN,
    feeBps: FEE_BPS,
    baseNet: BASE_NET,
    quoteNet: QUOTE_NET,
    totalShares: TOTAL_SHARES,
    levels: LEVELS,
  });
}

describe('depositSinglePlan matches the Rust golden vectors', () => {
  it('sellBase (base in)', () => {
    expect(plan('sellBase')).toEqual({
      swapIn: 33_897_681n,
      fee: 101_694n,
      swapNet: 33_795_987n,
      swapOut: 120_197_144n,
      baseDeposited: 66_102_319n,
      quoteDeposited: 120_197_144n,
      shares: 63_941_356n,
    });
  });
  it('buyBase (quote in)', () => {
    expect(plan('buyBase')).toEqual({
      swapIn: 33_652_173n,
      fee: 100_957n,
      swapNet: 33_551_216n,
      swapOut: 31_595_722n,
      baseDeposited: 31_595_722n,
      quoteDeposited: 66_347_827n,
      shares: 32_626_582n,
    });
  });
});

describe('depositSinglePlan invariants', () => {
  for (const side of ['sellBase', 'buyBase'] as const) {
    it(`${side}: fee is the program's ceil rule and input is fully accounted`, () => {
      const p = plan(side)!;
      expect(p.fee).toBe(feeAtoms(p.swapIn, FEE_BPS));
      expect(p.swapNet).toBe(p.swapIn - p.fee);
      // The swapped notional plus the imbalanced deposit equals the full input.
      const deposited = side === 'sellBase' ? p.baseDeposited : p.quoteDeposited;
      expect(deposited + p.swapIn).toBe(AMOUNT_IN);
      // The converted leg equals the ladder output.
      expect(side === 'sellBase' ? p.quoteDeposited : p.baseDeposited).toBe(p.swapOut);
      expect(p.swapIn).toBeLessThanOrEqual(AMOUNT_IN);
      expect(p.shares).toBeGreaterThan(0n);
    });

    it(`${side}: shares are non-dilutive (<= both pro-rata floors)`, () => {
      const p = plan(side)!;
      const baseAfter = side === 'sellBase' ? BASE_NET + p.swapNet : BASE_NET - p.swapOut;
      const quoteAfter = side === 'sellBase' ? QUOTE_NET - p.swapOut : QUOTE_NET + p.swapNet;
      const byBase = (p.baseDeposited * TOTAL_SHARES) / baseAfter;
      const byQuote = (p.quoteDeposited * TOTAL_SHARES) / quoteAfter;
      expect(p.shares).toBeLessThanOrEqual(byBase);
      expect(p.shares).toBeLessThanOrEqual(byQuote);
    });
  }

  it('rejects an empty ladder and a zero input', () => {
    expect(depositSinglePlan({
      side: 'sellBase', amountIn: AMOUNT_IN, feeBps: FEE_BPS,
      baseNet: BASE_NET, quoteNet: QUOTE_NET, totalShares: TOTAL_SHARES, levels: [],
    })).toBeNull();
    expect(depositSinglePlan({
      side: 'sellBase', amountIn: 0n, feeBps: FEE_BPS,
      baseNet: BASE_NET, quoteNet: QUOTE_NET, totalShares: TOTAL_SHARES, levels: LEVELS,
    })).toBeNull();
  });

  it('is monotonic in the amount (larger deposit mints at least as many shares)', () => {
    const small = plan('sellBase')!;
    const large = depositSinglePlan({
      side: 'sellBase', amountIn: AMOUNT_IN * 2n, feeBps: FEE_BPS,
      baseNet: BASE_NET, quoteNet: QUOTE_NET, totalShares: TOTAL_SHARES, levels: LEVELS,
    })!;
    expect(large.shares).toBeGreaterThan(small.shares);
  });
});

describe('withdrawSinglePlan matches the Rust golden vectors', () => {
  const args = (side: SingleSide) => ({
    side, shares: 100_000_000n, totalShares: TOTAL_SHARES,
    baseNet: BASE_NET, quoteNet: QUOTE_NET, feeBps: FEE_BPS, levels: LEVELS,
  });
  it('buyBase (base out, converts quote)', () => {
    expect(withdrawSinglePlan(args('buyBase'))).toEqual({
      baseOut: 100_000_000n,
      quoteOut: 200_000_000n,
      unwanted: 200_000_000n,
      fee: 600_000n,
      swapNet: 199_400_000n,
      converted: 145_778_554n,
      payout: 245_778_554n,
      capacityExceeded: false,
    });
  });
  it('sellBase (quote out, converts base)', () => {
    expect(withdrawSinglePlan(args('sellBase'))).toEqual({
      baseOut: 100_000_000n,
      quoteOut: 200_000_000n,
      unwanted: 100_000_000n,
      fee: 300_000n,
      swapNet: 99_700_000n,
      converted: 291_557_109n,
      payout: 491_557_109n,
      capacityExceeded: false,
    });
  });

  it('flags capacity when the ladder cannot absorb the unwanted leg', () => {
    const p = withdrawSinglePlan({
      side: 'buyBase', shares: 400_000_000n, totalShares: TOTAL_SHARES,
      baseNet: BASE_NET, quoteNet: QUOTE_NET, feeBps: FEE_BPS, levels: LEVELS,
    });
    expect(p.capacityExceeded).toBe(true);
  });

  it('payout equals the non-converted leg plus the ladder conversion', () => {
    for (const side of ['buyBase', 'sellBase'] as const) {
      const p = withdrawSinglePlan(args(side));
      const direct = side === 'buyBase' ? p.baseOut : p.quoteOut;
      expect(p.payout).toBe(direct + p.converted);
      expect(p.fee).toBe(feeAtoms(p.unwanted, FEE_BPS));
      const mathSide = side === 'buyBase' ? 'ask' : 'bid';
      expect(p.converted).toBe(walkLadder(LEVELS, mathSide, p.swapNet).out);
    }
  });
});

describe('single-sided display helpers', () => {
  it('minWithSlippage floors at the requested bps and clamps', () => {
    expect(minWithSlippage(10_000n, 50)).toBe(9_950n);
    expect(minWithSlippage(10_000n, 0)).toBe(10_000n);
    expect(minWithSlippage(10_000n, 20_000)).toBe(0n);
  });

  it('conversionImpactBps is zero at the reservation mid and null when uncomputable', () => {
    // Reservation sqrt price equal to the ladder midpoint (sqrt ~1.5*2^64).
    const pResSqrt = (3n << 64n) / 2n;
    const b = depositSinglePlan({
      side: 'sellBase', amountIn: AMOUNT_IN, feeBps: FEE_BPS,
      baseNet: BASE_NET, quoteNet: QUOTE_NET, totalShares: TOTAL_SHARES, levels: LEVELS,
    })!;
    const impact = conversionImpactBps({
      side: 'sellBase', swapNet: b.swapNet, converted: b.swapOut, pResSqrtQ64: pResSqrt,
    });
    expect(impact).not.toBeNull();
    expect(impact!).toBeGreaterThanOrEqual(0);
    expect(conversionImpactBps({ side: 'sellBase', swapNet: 0n, converted: 0n, pResSqrtQ64: pResSqrt })).toBeNull();
  });

  it('maxGrossInput bounds the swap leg the ladder can absorb', () => {
    const max = maxGrossInput(LEVELS, 'sellBase', FEE_BPS);
    expect(max).toBeGreaterThan(0n);
    const p = plan('sellBase')!;
    expect(p.swapIn).toBeLessThanOrEqual(max);
  });
});
